const imageUrl = $json.secure_url || '';

const previous = $('Article JSON').first().json;

return [{
  json: {
    ...previous,
    image_url: imageUrl,
    notion: {
      ...previous.notion,
      image: imageUrl
    }
  }
}];

// L'API Laravel (/api/n8n/articles/recent) renvoie un tableau JSON.
// Selon la config du nœud HTTP Request, n8n peut le livrer soit comme un
// seul item dont json est ce tableau, soit déjà "splitté" en plusieurs
// items (un par article) — on gère les deux cas.
const raw = (items.length === 1 && Array.isArray(items[0].json))
  ? items[0].json
  : items.map(i => i.json);

if (!raw.length) {
  return [{
    json: {
      topics_log: [],
      last_titles: [],
      last_title_1: '',
      last_title_2: '',
      last_subject: ''
    }
  }];
}

// Tri par date décroissante (sécurité au cas où l'API ne trierait pas)
raw.sort((a, b) => (a.published_at < b.published_at ? 1 : -1));

const last6 = raw.slice(0, 6);

const last_titles = last6
  .map(p => String(p.title || '').trim())
  .filter(Boolean);

const topics_log = last6
  .map(p => {
    const t = String(p.title || '').trim();
    const c = String(p.excerpt || '').trim();
    return `${t}\n${c}`.trim();
  })
  .filter(Boolean);

const last_subject = (last_titles[0] || '')
  .split(/\s+/)
  .slice(0, 3)
  .join(' ')
  .trim();

return [
  {
    json: {
      topics_log,
      last_titles,
      last_title_1: last_titles[0] || '',
      last_title_2: last_titles[1] || '',
      last_subject
    }
  }
];

// Récupère tous les items des 3 flux RSS
const allNews = $input.all().map(item => ({
  title: String(item.json.title || '').trim(),
  summary: String(item.json.contentSnippet || item.json.content || '')
    .replace(/<[^>]*>/g, '')  // strip HTML
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 280),
  date: item.json.isoDate || item.json.pubDate || '',
  source: item.json.link || ''
}));

// Tri par date décroissante, déduplique sur le titre
const seen = new Set();
const sorted = allNews
  .filter(n => n.title && !seen.has(n.title) && seen.add(n.title))
  .sort((a, b) => new Date(b.date) - new Date(a.date))
  .slice(0, 8); // Top 8 actus

// Récupère aussi le contexte historique du nœud précédent
const ctx = $('Title History').first().json;

return [{
  json: {
    last_titles: ctx.last_titles || [],
    last_subject: ctx.last_subject || '',
    news_block: sorted.map((n, i) => 
      `[${i+1}] ${n.title}\n    ${n.summary}`
    ).join('\n\n'),
    news_count: sorted.length
  }
}];

const out = [];
const MAX_NOTION_PROP = 1800;

function clamp(text, maxLen) {
  const t = String(text || "").trim();
  if (t.length <= maxLen) return t;
  return t.slice(0, maxLen - 1).trimEnd() + "…";
}

/**
 * Extrait le premier objet JSON complet du texte
 * (brace matching hors strings)
 */
function extractFirstJsonObject(raw) {
  let inString = false;
  let escaped = false;
  let depth = 0;
  let start = -1;

  for (let i = 0; i < raw.length; i++) {
    const ch = raw[i];

    if (inString) {
      if (escaped) {
        escaped = false;
        continue;
      }
      if (ch === "\\") {
        escaped = true;
        continue;
      }
      if (ch === "\"") {
        inString = false;
        continue;
      }
      continue;
    } else {
      if (ch === "\"") {
        inString = true;
        continue;
      }
      if (ch === "{") {
        if (depth === 0) start = i;
        depth++;
        continue;
      }
      if (ch === "}") {
        if (depth > 0) depth--;
        if (depth === 0 && start !== -1) {
          return raw.slice(start, i + 1);
        }
      }
    }
  }

  throw new Error("La sortie IA ne contient pas un objet JSON complet repérable (brace matching).");
}

/**
 * Répare les caractères de contrôle + guillemets non échappés DANS les strings JSON
 * Heuristique: si on voit un " dans une string et que le prochain char non-espace
 * n'est pas , } ] : (ou fin), alors on considère que c'est un guillemet interne → on l'échappe.
 */
function repairJsonText(jsonText) {
  let res = "";
  let inString = false;
  let escaped = false;

  for (let i = 0; i < jsonText.length; i++) {
    const ch = jsonText[i];

    if (!inString) {
      if (ch === "\"") inString = true;
      res += ch;
      continue;
    }

    // inString === true
    if (escaped) {
      res += ch;
      escaped = false;
      continue;
    }

    if (ch === "\\") {
      res += ch;
      escaped = true;
      continue;
    }

    if (ch === "\"") {
      // lookahead
      let j = i + 1;
      while (j < jsonText.length && /\s/.test(jsonText[j])) j++;
      const nxt = (j < jsonText.length) ? jsonText[j] : "";

      const isLikelyClosing = (nxt === ":" || nxt === "," || nxt === "}" || nxt === "]" || nxt === "");
      if (isLikelyClosing) {
        res += ch;
        inString = false;
      } else {
        // guillemet interne non échappé → on l'échappe
        res += "\\\"";
      }
      continue;
    }

    // Caractères de contrôle interdits dans une string JSON
    if (ch === "\n") { res += "\\n"; continue; }
    if (ch === "\r") { res += "\\r"; continue; }
    if (ch === "\t") { res += "\\t"; continue; }
    if (ch === "\b") { res += "\\b"; continue; }
    if (ch === "\f") { res += "\\f"; continue; }

    const code = ch.charCodeAt(0);
    if (code < 32) {
      res += "\\u" + code.toString(16).padStart(4, "0");
      continue;
    }

    res += ch;
  }

  return res;
}

function normalizeSpaces(s) {
  return String(s || "").trim().replace(/\s+/g, " ");
}

for (const item of items) {
  const raw = String(
    item.json.text ??
    item.json.candidates?.[0]?.content?.parts?.[0]?.text ??
    ""
  ).trim();

  const jsonChunk = extractFirstJsonObject(raw);
  const fixed = repairJsonText(jsonChunk);

  let data;
  try {
    data = JSON.parse(fixed);
  } catch (e) {
    // extra debug: contexte autour de la position indiquée
    const m = /position\s+(\d+)/i.exec(e.message);
    const pos = m ? Number(m[1]) : null;
    const start = pos !== null ? Math.max(0, pos - 120) : 0;
    const end = pos !== null ? Math.min(fixed.length, pos + 120) : Math.min(fixed.length, 240);

    throw new Error(
      "JSON invalide après réparation: " + e.message +
      "\n--- Contexte ---\n" +
      fixed.slice(start, end) +
      "\n--- Début JSON (200) ---\n" +
      fixed.slice(0, 200)
    );
  }

  const title = normalizeSpaces(data.title || "Post IA").slice(0, 90);
  const excerpt = normalizeSpaces(String(data.excerpt || "").replace(/\n+/g, " "));
  const hashtags = Array.isArray(data.hashtags) ? data.hashtags.filter(Boolean) : [];

  const imagePrompt = String(data.image_prompt || "").trim();
  const notionSummary = String(data.notion_summary || "").trim();
  const articleLong = String(data.article_long || "").trim();

  // Si tu veux t'assurer que l'article finit bien par la ligne hashtags:
  const hashtagsLine = hashtags.length ? hashtags.join(" ") : "";
  let articleFinal = articleLong;
  if (hashtagsLine) {
    // on compare en fin en ignorant espaces
    if (!articleFinal.trimEnd().endsWith(hashtagsLine)) {
      articleFinal = articleFinal.replace(/\n{3,}/g, "\n\n").trimEnd() + "\n\n" + hashtagsLine;
    }
  }

  const contenuForNotion = clamp(notionSummary || excerpt || title, MAX_NOTION_PROP);
  const nowIso = new Date().toISOString();

  out.push({
    json: {
      ai: {
        title,
        excerpt,
        hashtags,
        image_prompt: imagePrompt,
        notion_summary: notionSummary,
        article_long: articleFinal
      },
      notion: {
        titre: title,
        contenu: contenuForNotion,
        article_long: articleFinal,
        publicationDate: nowIso,
        extrait: excerpt,
        image: ""
      }
    }
  });
}

return out;

const data = $json;

const title = String(data.notion?.titre || data.ai?.title || '').trim();
const excerpt = String(data.notion?.extrait || data.ai?.excerpt || '').trim();
let content = String(data.notion?.article_long || data.ai?.article_long || '').trim();

// Le prompt du LLM produit article_long en commençant par le titre
// (cf. l'exemple de format dans "Basic LLM Chain" : "article_long":
// "TITRE\n\nIntro..."). Sans ça, le titre serait affiché deux fois sur
// la page (une fois dans le <h1>, une fois en tête du contenu).
const firstLine = content.split(/\n+/)[0]?.trim().toLowerCase() || '';
if (firstLine && firstLine === title.toLowerCase()) {
  content = content.split(/\n+/).slice(1).join('\n\n').trim();
}

return [{
  json: {
    title,
    excerpt,
    content,
    image: data.image_url || null,
    published_at: data.notion?.publicationDate || new Date().toISOString()
  }
}];

const created = $json; // {id, slug, title, url} renvoyé par l'API Laravel
const payload = $('Prepare Article Payload').first().json;

return [{
  json: {
    id: created.id,
    slug: created.slug,
    url: created.url,
    name: payload.title,
    property_titre: payload.title,
    property_extrait: payload.excerpt
  }
}];

// Agrège toutes les adresses, nettoie, déduplique, et sort une seule payload
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const emails = $items()
  .map(item => {
    const j = item.json;
    // Priorité à la propriété explicite, sinon fallback sur "name"
    const raw = j.property_email || j.Email || j.name || '';
    return String(raw).trim().toLowerCase();
  })
  // Filtre valeurs vides et invalides
  .filter(v => v && emailRegex.test(v))
  // Déduplique
  .filter((v, i, arr) => arr.indexOf(v) === i);

return [
  {
    emails,              // tableau : ["a@b.com", "c@d.com"]
    emails_csv: emails.join(','), // chaîne : "a@b.com,c@d.com"
    count: emails.length
  }
];
